def janken(self, my_hand, opponent_hand):
    if my_hand == opponent_hand:
        return 0
    elif (my_hand == 0 and opponent_hand == 1) or \
         (my_hand == 1 and opponent_hand == 2) or \
         (my_hand == 2 and opponent_hand == 0):
        return 2
    else:
        return 1

def print_result(result):
    if result == 0:
        print("あいこ")
    elif result == 1:
        print("負け")
    else:
        print("勝ち")

my_hand = int(input("自分: "))
opponent_hand = int(input("相手: "))

result = janken(my_hand, opponent_hand)
print_result(result)

import requests

def get_current_time():
    url = "https://api.aoikujira.com/time/get.php"
    response = requests.get(url)
    if response.status_code == 200:
        data = response.json()
        return f"現在時刻：{data['time']}"
    else:
        return "APIに接続できませんでした"

print(get_current_time())

