import csv
import requests
import tkinter as tk
from PIL import Image, ImageDraw, ImageFont

# 初期設定
PX = 1
PY = 1
W = 10
SZ = 55
map_url = "https://n3s.nadesi.com/image.php?f=20.csv"
treasure = 0
map_data = []

# データを読み込む
response = requests.get(map_url)
reader = csv.reader(response.text.splitlines(), delimiter=",")
for row in reader:
    map_data.append(row)

def draw_map():
    global PX, PY
    canvas.delete("all")
    for y in range(SZ):
        for x in range(SZ):
            tile_value = int(map_data[y][x])
            if tile_value == 0:
                color = "#ffffff"
            elif tile_value == 1:
                color = "#808080"
            elif tile_value == 2:
                color = "#ffff00"
            elif tile_value == 3:
                color = "#ffff00"
            elif tile_value == 4:
                color = "#ffff00"
            x1, y1, x2, y2 = x * W, y * W, (x + 1) * W, (y + 1) * W
            canvas.create_rectangle(x1, y1, x2, y2, fill=color, outline="#f0f0f0", width=1)
    # プレイヤーの描画
    canvas.create_text(PX * W + 5, PY * W + 7, text="♪", font=("Arial", 10), fill="#ff0000")

def tile_draw(x, y):
    tile_value = int(map_data[y][x])
    if tile_value == 0:
        color = "#ffffff"
    elif tile_value == 1:
        color = "#808080"
    elif tile_value == 2:
        color = "#ffff00"
    elif tile_value == 3:
        color = "#ffff00"
    elif tile_value == 4:
        color = "#ffff00"
    canvas.create_rectangle(x * W, y * W, (x + 1) * W, (y + 1) * W, fill=color, outline="#f0f0f0", width=1)

def key_press(event):
    global PX, PY
    x, y = PX, PY
    if event.keysym == "Up":
        y -= 1
    elif event.keysym == "Down":
        y += 1
    elif event.keysym == "Left":
        x -= 1
    elif event.keysym == "Right":
        x += 1
    if (x != PX) or (y != PY):
        canvas.delete("all")
        draw_map()
    else:
        tile_value = int(map_data[y][x])
        if tile_value < 0:
            return
        if tile_value == 1:
            return
        elif tile_value == 2:
            treasure += 1
            map_data[y][x] = 0
        elif tile_value == 3:
            print("罠に捕まった！スタートに戻ってしまった")
            PX, PY = 1, 1
            map_data[y][x] = 0
        elif tile_value == 4:
            if treasure == 0:
                print(f"出口を見つけたが、せっかくなら宝を持って帰りたい")
            else:
                print(f"宝を{treasure}個持ってゴール！ゲームクリア")
            root.destroy()
    PX, PY = x, y

root = tk.Tk()
canvas = tk.Canvas(root, width=SZ * W, height=SZ * W)
canvas.pack()

draw_map()

root.bind("<Key>", key_press)

root.mainloop()

